    @Test public void signedReadingAnchorsAndPrivateWireRefuseAliasesCapabilitiesAndMalformedCas() throws Exception {
        PlanetChildReadingPosition.Record record=new PlanetChildReadingPosition.Record("work","Work.ONE",1,"Passage.ONE");assertEquals("Work.ONE",PlanetChildReadingPosition.decode(record.dto()).id);
        Map<String,Object> reference=map("kind","work","id","Work.ONE","contentChecksum","a".repeat(64)),anchors=map("schemaVersion",1L,"anchorVersion",1L,"segments",Arrays.asList(map("anchorId","Passage.ONE","text","One")),"narration",null);
        PlanetChildReadingPosition.membership(record,reference,anchors,"One");Map<String,Object> wrongVersion=new LinkedHashMap<>(record.dto());wrongVersion.put("schemaVersion",true);denied(()->PlanetChildReadingPosition.decode(wrongVersion));Map<String,Object> extra=new LinkedHashMap<>(record.dto());extra.put("locale","ru");denied(()->PlanetChildReadingPosition.decode(extra));
        Map<String,Object> duplicate=new LinkedHashMap<>(anchors);duplicate.put("segments",Arrays.asList(map("anchorId","Passage.ONE","text","O"),map("anchorId","Passage.ONE","text","ne")));denied(()->PlanetChildReadingPosition.anchors(duplicate,"One"));PlanetChildReadingPosition.Record unknown=new PlanetChildReadingPosition.Record("work","Work.ONE",2,"Passage.ONE");denied(()->PlanetChildReadingPosition.membership(unknown,reference,anchors,"One"));
        Map<String,Object> cueGap=new LinkedHashMap<>(anchors);cueGap.put("narration",map("assetId","Audio.ONE","sha256","a".repeat(64),"sampleRate",8000L,"frameCount",8000L,"cues",Arrays.asList(map("anchorId","Passage.ONE","startFrame",1L,"endFrame",8000L))));denied(()->PlanetChildReadingPosition.anchors(cueGap,"One"));
        Map<String,Object> write=base("2".repeat(32));write.put("reference",reference);write.put("expectedRevision",0L);write.put("position",record.dto());assertEquals(record,PlanetChildDataTransport.decodeV2("rememberReadingPosition",write).readingPosition);
        for(String key:Arrays.asList("profileId","approved","url","locale","anchorMap")){Map<String,Object> untrusted=new LinkedHashMap<>(write);untrusted.put(key,true);denied(()->PlanetChildDataTransport.decodeV2("rememberReadingPosition",untrusted));}for(Object invalid:Arrays.asList(true,-1L,0.5d,9007199254740990L)){Map<String,Object> bad=new LinkedHashMap<>(write);bad.put("expectedRevision",invalid);denied(()->PlanetChildDataTransport.decodeV2("rememberReadingPosition",bad));}
    }
